async function copyName(text){try{if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);toast('Copied');return true;}catch{}}const previous=document.activeElement,field=document.createElement('textarea');field.value=text;field.readOnly=true;field.setAttribute('aria-hidden','true');field.style.cssText='position:fixed;left:-9999px;top:0;opacity:0';document.body.append(field);field.select();let copied=false;try{copied=!!document.execCommand?.('copy');}finally{field.remove();previous?.focus?.({preventScroll:true});}if(copied){toast('Copied');return true;}throw Error('Copy unavailable');}catch{toast('Could not copy text');return false;}}
