async function api(table,method='GET',body=null,query=''){
 const response=await fetch(API+(table.startsWith('rpc/')?'rpc/'+PREFIX+table.slice(4):PREFIX+table)+query,{method,headers:{apikey:KEY,'Content-Type':'application/json',Prefer:'return=representation,resolution=merge-duplicates'},...(body?{body:JSON.stringify(body)}:{})});
 if(!response.ok){const e=await response.json().catch(()=>({message:response.statusText}));throw Error(e.message||'Database request failed');}return response.status===204?[]:response.json();
}
async function load(quiet=false){if(loading||pending||pointer||squareDrag||androidHold||quickListening||quickSaving)return;loading=true;if(!quiet)status('Syncing…');try{const [p,t,c]=await Promise.all([api('projects','GET',null,'?select=*&order=position,created_at'),api('tasks','GET',null,'?select=*&order=position,created_at'),loadCells()]);projects=p;tasks=t;cells=new Map(c.map(x=>[squareKey(x),x]));loaded=true;render();status('All changes saved');$('error').hidden=true;}catch(e){error(e);}finally{loading=false;}}
async function mutate(table,method,body,id){pending++;status('Saving…');try{const result=await api(table,method,body,id?'?id=eq.'+encodeURIComponent(id):'');$('error').hidden=true;return result;}catch(e){error(e);throw e;}finally{pending--;if(!pending&&$('error').hidden)status('All changes saved');}}
async function updateTask(id,patch){const task=tasks.find(t=>t.id===id);if(!task)return;const old={...task};Object.assign(task,patch);render();try{const [saved]=await mutate('tasks','PATCH',patch,id);if(!saved)throw Error('Task was removed. Refresh to continue.');Object.assign(task,saved);render();}catch(e){Object.assign(task,old);render();error(e);}}
function cellHint(day){return `${Number(day.slice(5,7))}-${day.slice(8)} ${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][date(day).getUTCDay()]} · ${diff(day,localToday())}`;}
function dateHint(day){const n=diff(day,localToday()),weekday=date(day).toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'});return `${n} day${Math.abs(n)===1?'':'s'} out · ${day.slice(5)} ${weekday}`;}
function itemDaysOut(id,kind='task'){let relevant=[...cells.values()].filter(c=>c.status&&(kind==='project'?c.project_id===id:c.task_id===id));if(kind==='project'&&!relevant.length){const childIds=new Set(tasks.filter(t=>t.project_id===id).map(t=>t.id));relevant=[...cells.values()].filter(c=>c.status&&childIds.has(c.task_id));}let next=Infinity,recent=-Infinity;for(const cell of relevant){const n=diff(cell.day,localToday());if(n>=0)next=Math.min(next,n);else recent=Math.max(recent,n);}return Number.isFinite(next)?String(next):Number.isFinite(recent)?String(recent):'';}
function androidAddRow(type,projectId=''){const key=type==='project'?'project':projectId,name=projects.find(p=>p.id===projectId)?.name||'';return `<div class="android-add-row"><input class="inline-create" data-create="${type}" data-project-id="${projectId}" data-key="${key}" value="${esc(drafts.get(key)||'')}" aria-label="${esc(type==='project'?'New project name':'New task name in '+name)}" placeholder="＋ New ${type}" maxlength="200" autocomplete="off" enterkeyhint="done" ${creatingRows.has(key)?'disabled':''}></div>`;}
function androidName(item,kind){const number=itemDaysOut(item.id,kind),todayStatus=kind==='task'?dayStatus(item,localToday(),'task'):null;return `<div class="android-item android-${kind}-row ${todayStatus?'android-today-'+todayStatus:''}" data-${kind}="${item.id}"><button class="android-name android-${kind}-name" data-mobile-table="${kind==='project'?'projects':'tasks'}" data-mobile-id="${item.id}" aria-label="${esc(item.name)}" aria-description="Long press to open notes">${esc(item.name)}</button><span class="android-days" aria-label="${number?number+' days out':'No scheduled date'}">${number}</span></div>`;}
function quickEntry(){return `<div class="android-quick-entry"><div class="quick-entry-row"><input id="quick-task-input" type="text" value="${esc(quickDraft)}" maxlength="200" autocomplete="off" enterkeyhint="done" aria-label="Add task to General" placeholder="Add to General…" ${quickSaving||!loaded?'disabled':''}><button type="button" id="quick-mic" aria-label="${quickListening?'Stop voice input':'Start voice input'}" aria-pressed="${quickListening}" ${quickSaving||!loaded?'disabled':''}><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></svg></button><button type="button" id="quick-add" ${quickSaving||!quickDraft.trim()||!loaded?'disabled':''}>${quickSaving?'Adding…':'Add'}</button></div><span id="quick-message" role="status" ${quickMessage?'':'hidden'}>${esc(quickMessage)}</span></div>`;}
function syncQuickEntry(){const input=$('quick-task-input');if(!input)return;if(input.value!==quickDraft)input.value=quickDraft;input.disabled=quickSaving||!loaded;$('quick-add').disabled=quickSaving||!quickDraft.trim()||!loaded;$('quick-add').textContent=quickSaving?'Adding…':'Add';$('quick-mic').disabled=quickSaving||!loaded;$('quick-mic').setAttribute('aria-pressed',String(quickListening));$('quick-mic').setAttribute('aria-label',quickListening?'Stop voice input':'Start voice input');$('quick-message').textContent=quickMessage;$('quick-message').hidden=!quickMessage;}
function stopQuickVoice(detach=false){const recognizer=quickRecognizer;if(detach)quickRecognizer=null;quickListening=false;quickMessage=quickDraft.trim()?'Ready to add.':'';try{recognizer?.stop();}catch{}syncQuickEntry();}
function startQuickVoice(){if(!androidMode||quickSaving||quickListening||!loaded)return;const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){quickMessage='Voice input is unavailable here. Type or use your keyboard microphone.';syncQuickEntry();return;}const base=quickDraft.trim();let recognizer,failed=false;try{recognizer=new Speech();quickRecognizer=recognizer;recognizer.lang=navigator.language||'en-US';recognizer.interimResults=true;recognizer.continuous=false;recognizer.onresult=event=>{if(quickRecognizer!==recognizer||quickSaving)return;let transcript='';for(let i=0;i<event.results.length;i++)transcript+=(transcript?' ':'')+(event.results[i][0]?.transcript||'');quickDraft=[base,transcript.trim()].filter(Boolean).join(' ');quickRequestId=null;quickMessage=quickDraft.length>200?'Keep the task name under 200 characters.':'Listening…';syncQuickEntry();};recognizer.onerror=event=>{if(quickRecognizer!==recognizer)return;failed=true;quickRecognizer=null;quickListening=false;quickMessage=event.error==='not-allowed'||event.error==='service-not-allowed'?'Microphone access was blocked. You can still type.':event.error==='no-speech'?'No speech detected. Tap the microphone to try again.':event.error==='audio-capture'?'No microphone found. You can still type.':'Voice input could not connect. You can still type.';syncQuickEntry();};recognizer.onend=()=>{if(quickRecognizer!==recognizer)return;quickRecognizer=null;quickListening=false;if(!failed)quickMessage=quickDraft.trim()?'Ready to add.':'';syncQuickEntry();};quickListening=true;quickMessage='Listening…';syncQuickEntry();recognizer.start();}catch{quickRecognizer=null;quickListening=false;quickMessage='Could not start voice input. You can still type.';syncQuickEntry();}}
async function addQuickTask(){if(!androidMode||quickSaving||!loaded)return;const name=quickDraft.trim();if(!name)return;if(name.length>200){quickMessage='Keep the task name under 200 characters.';syncQuickEntry();return;}stopQuickVoice(true);quickSaving=true;quickRequestId=quickRequestId||crypto.randomUUID();quickMessage='Adding to General…';syncQuickEntry();try{const today=localToday(),result=await mutate('rpc/quick_add','POST',{p_name:name,p_day:today,p_task_id:quickRequestId});const project=projects.find(p=>p.id===result.project.id);if(project)Object.assign(project,result.project);else projects.push(result.project);const task=tasks.find(t=>t.id===result.task.id);if(task)Object.assign(task,result.task);else tasks.push(result.task);projects.sort((a,b)=>a.position-b.position);tasks.sort((a,b)=>a.position-b.position);const square=squareRow('task',result.task.id,result.task.start_date||today,'assigned');cells.set(squareKey(square),square);quickDraft='';quickRequestId=null;quickMessage='Added to General for today.';}catch(e){quickMessage='Could not add: '+e.message;}finally{quickSaving=false;render();syncQuickEntry();}}
$('grid').addEventListener('input',e=>{if(e.target.id!=='quick-task-input')return;const value=e.target.value;if(quickListening)stopQuickVoice(true);quickDraft=value;quickRequestId=null;quickMessage='';syncQuickEntry();});
