$('grid').addEventListener('pointermove',e=>{if(!pointer)return;const p=pointer;if(p.mode==='square')return;if(p.mode==='paint'){p.endIndex=cellAt(e,p.line);paintPreview(p);return;}const delta=Math.round((e.clientX-p.x)/cw);if(Math.abs(e.clientX-p.x)>3||Math.abs(e.clientY-p.y)>3)p.moved=true;let s=p.oldStart,f=p.oldEnd;if(p.mode==='draw'){const i=cellAt(e,p.line);s=add(start,Math.min(p.index,i));f=add(start,Math.max(p.index,i));}else if(p.mode==='move'){s=add(p.oldStart,delta);f=add(p.oldEnd,delta);}else if(p.mode==='start'){s=add(p.oldStart,delta);if(s>f)s=f;}else{f=add(p.oldEnd,delta);if(f<s)f=s;}p.newStart=s;p.newEnd=f;let selection=p.line.querySelector('.selection');if(!selection){selection=document.createElement('div');selection.className='selection';p.line.append(selection);}selection.style.left=Math.max(0,diff(s,start))*cw+'px';selection.style.width=(Math.min(days,diff(f,start)+1)-Math.max(0,diff(s,start)))*cw+'px';selection.title=`${s} → ${f}`;});
