function dropLocation(e){const row=e.target.closest('.row');if(!row)return null;if(draggingKind==='project'){if(row.classList.contains('new-project-row'))return {row,targetId:null,after:true};const projectId=row.dataset.project;if(!projectId)return null;const header=document.querySelector(`.project-row[data-project="${projectId}"]`);return {row:header,targetId:projectId,after:e.clientY>header.getBoundingClientRect().top+header.getBoundingClientRect().height/2};}if(!row.dataset.project)return null;return {row,projectId:row.dataset.project,targetId:row.dataset.task||null,after:!!row.dataset.task&&e.clientY>row.getBoundingClientRect().top+row.getBoundingClientRect().height/2};}
