function renderComments(){$('new-comment').disabled=!commentsReady||commentLoading;$('comment-list').innerHTML=commentItems.map(c=>`<article class="comment-entry" data-comment="${c.id}"><div class="comment-meta"><time datetime="${esc(c.created_at)}">${esc(new Date(c.created_at).toLocaleString())}</time><button type="button" data-delete-comment="${c.id}" aria-label="Delete comment">×</button></div><textarea data-comment-id="${c.id}" aria-label="Comment entry" placeholder="Write a comment…" rows="7">${esc(c.body)}</textarea><span class="comment-status" data-comment-status="${c.id}" role="status">${c._savedBody===null?'New comment — saves as you type':'Saved'}</span></article>`).join('');if(commentsReady&&!commentItems.length)$('comments-message').textContent='No comments yet.';else if(commentsReady)$('comments-message').textContent='';}
async function loadEditorComments(){if(!editor)return;const current=editor;commentsReady=false;commentLoading=true;commentItems=[];$('retry-comments').hidden=true;$('comments-message').textContent='Loading comments…';renderComments();try{const column=current.table==='projects'?'project_id':'task_id';let rows=[],offset=0;while(true){const page=await api('comments','GET',null,`?${column}=eq.${encodeURIComponent(current.id)}&order=created_at.desc,id&limit=1000&offset=${offset}`);rows.push(...page);if(page.length<1000)break;offset+=1000;}if(editor!==current)return;commentItems=rows.map(c=>({...c,_savedBody:c.body}));commentsReady=true;}catch(e){if(editor!==current)return;$('comments-message').textContent='Could not load comments: '+e.message;$('retry-comments').hidden=false;}finally{if(editor===current){commentLoading=false;renderComments();}}}
