async function openEditor(table,id){if(androidMode&&quickListening)stopQuickVoice(true);if(editor&&!await closeEditor())return;const item=(table==='tasks'?tasks:projects).find(x=>x.id===id);if(!item)return;editor={table,id};$('detail-type').textContent=androidMode?item.name:table==='tasks'?'TASK DETAILS':'PROJECT DETAILS';$('detail-name').value=item.name;$('notes').innerHTML=sanitize(item.notes||'');$('detail-message').textContent='Changes save automatically';$('drawer').hidden=$('drawer-shade').hidden=false;editorBaseline=editorState();clearCommentTimers();loadEditorComments();if(!androidMode)$('detail-name').focus();}
