$('add-link').onmousedown=e=>e.preventDefault();$('add-link').onclick=()=>{const url=prompt('Link URL (https://…)');if(!url)return;if(!/^https?:\/\//i.test(url)){toast('Use a full https:// or http:// URL');return;}$('notes').focus();document.execCommand('createLink',false,url);queueEditorSave();};
$('notes').addEventListener('paste',e=>{e.preventDefault();const html=e.clipboardData.getData('text/html'),plain=e.clipboardData.getData('text/plain');document.execCommand('insertHTML',false,html?sanitize(html):esc(plain).replace(/\n/g,'<br>'));queueEditorSave();});
function setDeleteMode(active){deleteMode=active;$('trash-mode').setAttribute('aria-pressed',String(active));$('grid').classList.toggle('delete-mode',active);for(const b of $('paint-tools').querySelectorAll('[data-paint]'))b.setAttribute('aria-pressed',String(!active&&b.dataset.paint===paintMode));}
$('trash-mode').onclick=async()=>{if(editor&&!await closeEditor())return;setDeleteMode(!deleteMode);if(deleteMode)toast('Click a project or task name to delete. Escape cancels.');};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&deleteMode)setDeleteMode(false);});
async function deleteItem(table,id){if(deleting)return false;deleting=true;$('trash-mode').disabled=$('delete-item').disabled=true;try{await paintQueue;if(editorSavePromise)await editorSavePromise;if(commentJobs.size)await Promise.all(commentJobs.values());if(pending){toast('Wait for changes to finish saving, then try again.');return false;}const item=(table==='projects'?projects:tasks).find(x=>x.id===id);if(!item)return false;const count=tasks.filter(t=>t.project_id===id).length,message=table==='projects'?`Delete project “${item.name}” and all ${count} of its tasks?`:`Delete task “${item.name}”?`;if(!confirm(message))return false;if(editor?.id===id&&editor.table===table){clearTimeout(editorTimer);clearCommentTimers();if(commentJobs.size)await Promise.all(commentJobs.values());}await mutate(table,'DELETE',null,id);const removedTasks=new Set(table==='projects'?tasks.filter(t=>t.project_id===id).map(t=>t.id):[id]);if(table==='projects'){projects=projects.filter(x=>x.id!==id);tasks=tasks.filter(x=>x.project_id!==id);collapsed.delete(id);drafts.delete(id);}else tasks=tasks.filter(x=>x.id!==id);for(const [key,cell] of cells)if(removedTasks.has(cell.task_id)||(table==='projects'&&cell.project_id===id))cells.delete(key);if(editor?.id===id&&editor.table===table)closeEditor(true);setDeleteMode(false);render();toast(table==='projects'?'Project deleted':'Task deleted');return true;}catch{return false;}finally{deleting=false;$('trash-mode').disabled=$('delete-item').disabled=false;}}
$('delete-item').onclick=()=>{if(editor)deleteItem(editor.table,editor.id);};
load();setInterval(()=>{if(!document.hidden&&!editor&&!document.activeElement?.closest('.grid'))load(true);},15000);
